head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil15003";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_fillGen();
        scwin.init_rowCopy();
        scwin.init_conds();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil15003.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "img_38", fn: function(){ return ((dlt_announcementBbsAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attach.fileSurFix"); })()) === 'HWP'); } }, { id: "txt_text39", fn: function(){ return ((dlt_announcementBbsAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attach.fileSurFix"); })()) === 'HWP'); } }, { id: "img_41", fn: function(){ return ((dlt_announcementBbsAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attach.fileSurFix"); })()) === 'XLS'); } }, { id: "txt_text42", fn: function(){ return ((dlt_announcementBbsAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attach.fileSurFix"); })()) === 'XLS'); } }, { id: "img_44", fn: function(){ return ((dlt_announcementBbsAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attach.fileSurFix"); })()) === 'DOC'); } }, { id: "txt_text45", fn: function(){ return ((dlt_announcementBbsAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attach.fileSurFix"); })()) === 'DOC'); } }, { id: "img_47", fn: function(){ return ((dlt_announcementBbsAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attach.fileSurFix"); })()) === 'PPT'); } }, { id: "txt_text48", fn: function(){ return ((dlt_announcementBbsAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attach.fileSurFix"); })()) === 'PPT'); } }, { id: "img_50", fn: function(){ return ((dlt_announcementBbsAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attach.fileSurFix"); })()) === 'PDF'); } }, { id: "txt_text51", fn: function(){ return ((dlt_announcementBbsAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attach.fileSurFix"); })()) === 'PDF'); } }, { id: "c_otherwise_52", fn: function(){ return (!(((dlt_announcementBbsAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attach.fileSurFix"); })()) === 'HWP') || ((dlt_announcementBbsAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attach.fileSurFix"); })()) === 'XLS') || ((dlt_announcementBbsAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attach.fileSurFix"); })()) === 'DOC') || ((dlt_announcementBbsAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attach.fileSurFix"); })()) === 'PPT') || ((dlt_announcementBbsAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attach.fileSurFix"); })()) === 'PDF'))); } }, { id: "c_when_67", fn: function(){ return (!(String(((dma_announcement.get("nextBbsVO") ?? (() => { throw new Error("unresolved:" + "announcement.nextBbsVO"); })())) == null ? '' : ((dma_announcement.get("nextBbsVO") ?? (() => { throw new Error("unresolved:" + "announcement.nextBbsVO"); })()))).length === 0)); } }, { id: "c_otherwise_71", fn: function(){ return (!((!(String(((dma_announcement.get("nextBbsVO") ?? (() => { throw new Error("unresolved:" + "announcement.nextBbsVO"); })())) == null ? '' : ((dma_announcement.get("nextBbsVO") ?? (() => { throw new Error("unresolved:" + "announcement.nextBbsVO"); })()))).length === 0)))); } }, { id: "c_when_79", fn: function(){ return (!(String(((dma_announcement.get("preBbsVO") ?? (() => { throw new Error("unresolved:" + "announcement.preBbsVO"); })())) == null ? '' : ((dma_announcement.get("preBbsVO") ?? (() => { throw new Error("unresolved:" + "announcement.preBbsVO"); })()))).length === 0)); } }, { id: "c_otherwise_83", fn: function(){ return (!((!(String(((dma_announcement.get("preBbsVO") ?? (() => { throw new Error("unresolved:" + "announcement.preBbsVO"); })())) == null ? '' : ((dma_announcement.get("preBbsVO") ?? (() => { throw new Error("unresolved:" + "announcement.preBbsVO"); })()))).length === 0)))); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_fillGen
 * @description 제너레이터 채움 — 진입점(onpageload)에서 순차 실행.
 * @param {String} boxId boxId
 * @returns {void}
 * @hidden N
 */
scwin.init_fillGen = function (boxId) {
    // 채우지 못한 자리를 모은다(동작은 계속 — 화면은 종전과 같다).
    const genSkip = [];
    let genCleared = 0;
    const genFills = [{ genId: "c_foreach_34", entity: "dlt_announcementBbsAttachVO", countIds: [], cells: [{ childId: "__rc3", fn: function (v, i) { return " " + String(v("attachFileNm")); } }, { childId: "__rc4", fn: function (v, i) { return " " + String(v("attachFileNm")); } }, { childId: "__rc5", fn: function (v, i) { return " " + String(v("attachFileNm")); } }, { childId: "__rc6", fn: function (v, i) { return " " + String(v("attachFileNm")); } }, { childId: "__rc7", fn: function (v, i) { return " " + String(v("attachFileNm")); } }, { childId: "__rc8", fn: function (v, i) { return " " + String(v("attachFileNm")); } }] }];
    const gf = genFills;
    for (let g = 0; g < gf.length; g++) {
        const f = gf[g];
        if (boxId && f.entity !== boxId) { continue; }
        const gen = $c.util.getComponent(f.genId);
        const ds = $c.util.getComponent(f.entity);
        if (!gen || !ds || !ds.getTotalRow) { genSkip.push({ gen: f.genId, box: f.entity, why: !gen ? 'no-generator' : 'no-box' }); continue; }
        const n = ds.getRowCount();
        if (!n) { genSkip.push({ gen: f.genId, box: f.entity, why: 'empty-box' }); continue; }
        // 멱등 — 이미 채워진 제너레이터는 건너뛴다(플래그 없이 컴포넌트 상태로 판단).
        //   단, 상자를 지정해 «다시 그리라» 고 부른 경우(데이터가 새로 담긴 때)는 비우고 다시 채운다.
        if (gen.getLength && gen.getLength() > 0) {
            if (!boxId) { continue; }
            const had = gen.getLength();
            while (gen.getLength() > 0) { gen.removeChild(); }
            genCleared += had;
        }
        let row = 0;
        const cell = function (col) { const v = ds.getCellData(row, col); return (v === undefined || v === null) ? '' : v; };
        for (let i = 0; i < n; i++) {
            row = i;
            gen.insertChild(i);
            for (let c = 0; c < f.cells.length; c++) {
                const ch = gen.getChild(i, f.cells[c].childId);
                if (!ch || !ch.setValue) { continue; }
                ch.setValue(f.cells[c].fn(cell, i));
            }
            for (let k = 0; k < f.countIds.length; k++) {
                const cn = gen.getChild(i, f.countIds[k]);
                if (cn && cn.setValue) { cn.setValue(String(i + 1)); }
            }
            // 행 조건 — 마지막 행에만 보이는 자리.
            if (f.rowConds) {
                for (let rc = 0; rc < f.rowConds.length; rc++) {
                    const rn = gen.getChild(i, f.rowConds[rc].childId);
                    if (!rn) { continue; }
                    const show = (f.rowConds[rc].kind === 'last') ? (i === n - 1) : true;
                    if (rn.setStyle) { rn.setStyle('display', show ? '' : 'none'); }
                }
            }
        }
    }
    if (genSkip.length) {
        // 우리 계측이 읽는 자리 — 화면 동작에는 영향이 없다.
        scwin.genFillSkipped = genSkip;
    }
    if (genCleared) { scwin.genFillCleared = (scwin.genFillCleared || 0) + genCleared; }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "__rb2", fn: function () { return String(String(String(dma_announcement.get("contnContn")) == null ? '' : String(dma_announcement.get("contnContn"))).split(String.fromCharCode(10)).join('<br/>')); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

// [A] 초기 목록 미해결 — jldfil15003: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_FileDown_onclick
 * @description btn_FileDown 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_FileDown_onclick = async function(e){
    try {
        await scwin.fileDown('' + dlt_announcementBbsAttachVO.getCellData(0, "saveFileNm") + '','' + dlt_announcementBbsAttachVO.getCellData(0, "attachFileNm") + '','' + dlt_announcementBbsAttachVO.getCellData(0, "filePath") + '')

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil15003.btn_FileDown_onclick' }); }
};

/**
 * @method
 * @name btn_GoURL_onclick
 * @description btn_GoURL 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_GoURL_onclick = async function(e){
    try {
        await scwin.goURL('list')

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil15003.btn_GoURL_onclick' }); }
};

/**
 * @method
 * @name btn_GoURL_2_onclick
 * @description 「${announcement.nextBbsVO.title}」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_GoURL_2_onclick = async function(e){
    try {
        await scwin.goURL('detail',(String(((dma_announcement.get("contnId") ?? (() => { throw new Error("unresolved:" + "announcement.nextBbsVO.contnId"); })())) == null ? '' : ((dma_announcement.get("contnId") ?? (() => { throw new Error("unresolved:" + "announcement.nextBbsVO.contnId"); })()))).indexOf('$' + '{') >= 0 ? '' : String(((dma_announcement.get("contnId") ?? (() => { throw new Error("unresolved:" + "announcement.nextBbsVO.contnId"); })())) == null ? '' : ((dma_announcement.get("contnId") ?? (() => { throw new Error("unresolved:" + "announcement.nextBbsVO.contnId"); })())))))

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil15003.btn_GoURL_2_onclick' }); }
};

/**
 * @method
 * @name btn_GoURL_3_onclick
 * @description 「${announcement.preBbsVO.title}」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_GoURL_3_onclick = async function(e){
    try {
        await scwin.goURL('detail',(String(((dma_announcement.get("contnId") ?? (() => { throw new Error("unresolved:" + "announcement.preBbsVO.contnId"); })())) == null ? '' : ((dma_announcement.get("contnId") ?? (() => { throw new Error("unresolved:" + "announcement.preBbsVO.contnId"); })()))).indexOf('$' + '{') >= 0 ? '' : String(((dma_announcement.get("contnId") ?? (() => { throw new Error("unresolved:" + "announcement.preBbsVO.contnId"); })())) == null ? '' : ((dma_announcement.get("contnId") ?? (() => { throw new Error("unresolved:" + "announcement.preBbsVO.contnId"); })())))))

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil15003.btn_GoURL_3_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_GoURL
 * @description Go URL 서버 호출
 * @param {*} action 제출 주소(호출부가 as-is form.action 으로 정하던 분기별 URL · 생략 시 기본 주소)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_GoURL = async function (action) {
    const sbmOptions = {
        id: "tx_fn_GoURL",
        method: "post",
        action: action ?? "/support/announcement.do",
        ref: "dma_GoURLReq",
        target: "dlt_announcementBbsAttachVO=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name tx_fn_FileDown
 * @description File Down 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_FileDown = async function () {
    try { return await $c.data.downFile("http://krx.co.kr/servlets/exkrx/util/Download", "", ($c.util.getComponent("dma_FileDownReq") ? $c.util.getComponent("dma_FileDownReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

/**
 * @method
 * @name goURL
 * @description go URL 처리
 * @param {String} flag flag
 * @param {String} contnId contnId
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.goURL = async function (flag, contnId) {
    if (flag === 'list') {
        $c.util.getComponent('dma_GoURLReq').set('method', 'searchIntroBbs');
        { const __nr = await scwin.tx_fn_GoURL('announcement.do'); if (__nr && __nr.responseJSON && __nr.responseJSON.success === true) { $c.win.moveUrl("/jldfil15002/jldfil15002.xml", { "method": 'searchIntroBbs', "contnId": contnId }); } };
    } else {
        if (flag === 'detail') {
            $c.util.getComponent('dma_GoURLReq').set('method', 'searchIntroBbsDetail');
            $c.util.getComponent('dma_GoURLReq').set('contnId', contnId);
            { const __nr = await scwin.tx_fn_GoURL('announcement.do'); if (__nr && __nr.responseJSON && __nr.responseJSON.success === true) { $c.win.moveUrl("/jldfil15002/jldfil15002.xml", { "method": 'searchIntroBbs', "contnId": contnId }); } };
        }
    }
};

/**
 * @method
 * @name fileDown
 * @description file Down 처리
 * @param {String} attachFileNm attachFileNm
 * @param {String} saveFileNm saveFileNm
 * @param {*} fileDir fileDir
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fileDown = async function (attachFileNm, saveFileNm, fileDir) {
    document.charset = "euc-kr";
    $c.util.getComponent('dma_GoURLReq').set('fileName', attachFileNm);
    $c.util.getComponent('dma_GoURLReq').set('realName', saveFileNm);
    $c.util.getComponent('dma_GoURLReq').set('fileDir', fileDir);
    await scwin.tx_fn_FileDown();
};
